//io Demo Page  

document.addEventListener('DOMContentLoaded', function() {
    const urlElement = document.querySelector('.animated-url');
    const comingSoonElement = document.querySelector('.coming-soon');
    
    // Weather API functionality using Open-Meteo 
    const ZURICH_LAT = 47.3769;
    const ZURICH_LON = 8.5417;
    
    // Discharge data URLs generated by GitHub Actions
    const DISCHARGE_URLS = {
        limmat: 'data/discharge-limmat.json',
        rheinfall: 'data/discharge-rheinfall.json'
    };
    const DISCHARGE_UPDATE_INTERVAL = 30 * 60 * 1000; // 30 minutes
    
    async function getZurichWeather() {
        try {
            const response = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${ZURICH_LAT}&longitude=${ZURICH_LON}&current=temperature_2m,weather_code&timezone=auto`);
            const data = await response.json();
            
            if (data.current) {
                const tempValue = document.getElementById('temp-value');
                const weatherDesc = document.getElementById('weather-desc');
                
                // Update temperature
                tempValue.textContent = Math.round(data.current.temperature_2m);
                
                // Convert weather code to description
                const weatherDescription = getWeatherDescription(data.current.weather_code);
                weatherDesc.textContent = weatherDescription;
                
                // Add temperature-based color animation
                const temp = data.current.temperature_2m;
                const weatherContainer = document.querySelector('.weather-container');
                
                if (temp < 0) {
                    weatherContainer.style.background = 'rgba(135, 206, 250, 0.2)'; // Cold - light blue
                } else if (temp > 20) {
                    weatherContainer.style.background = 'rgba(255, 165, 0, 0.2)'; // Warm - orange
                } else {
                    weatherContainer.style.background = 'rgba(255, 255, 255, 0.1)'; // Normal - default
                }
            }
        } catch (error) {
            console.error('Error fetching weather data:', error);
            document.getElementById('weather-desc').textContent = 'Weather unavailable';
        }
    }
    
    function formatDischargeTrend(trend, delta) {
        const deltaNumber = Number(delta);
        const timeWindow = '24h'; // Calculation period

        if (trend === 'steady') {
            return `Trend (${timeWindow}): stable`;
        }

        if (trend === 'rising') {
            if (Number.isNaN(deltaNumber)) return `Trend (${timeWindow}): rising`;
            return `Trend (${timeWindow}): rising (+${deltaNumber.toFixed(1)} m3/s)`;
        }

        if (trend === 'falling') {
            if (Number.isNaN(deltaNumber)) return `Trend (${timeWindow}): falling`;
            return `Trend (${timeWindow}): falling (${deltaNumber.toFixed(1)} m3/s)`;
        }

        return `Trend (${timeWindow}): no comparison data yet`;
    }

    function updateTrendArrow(trend, elementId = 'trend-arrow') {
        const trendArrow = document.getElementById(elementId);
        if (!trendArrow) return;

        switch(trend) {
            case 'rising':
                trendArrow.textContent = '↑';
                trendArrow.style.color = '#1e3a8a';
                break;
            case 'falling':
                trendArrow.textContent = '↓';
                trendArrow.style.color = '#1e3a8a';
                break;
            case 'steady':
            default:
                trendArrow.textContent = '→';
                trendArrow.style.color = '#1e3a8a';
                break;
        }
    }

    async function getDischargeData(dataUrl, suffix = '') {
        try {
            const STATION_PAGE = suffix ? 
                'https://www.hydrodaten.admin.ch/de/seen-und-fluesse/stationen-und-daten/2288' :
                'https://www.hydrodaten.admin.ch/de/seen-und-fluesse/stationen-und-daten/2099';
            
            const response = await fetch(`${dataUrl}?t=${Date.now()}`, { cache: 'no-store' });
            if (!response.ok) throw new Error('Discharge JSON fetch failed: ' + response.status);
            const data = await response.json();

            const dischargeValueId = suffix ? `discharge-value${suffix}` : 'discharge-value';
            const dischargeStatusId = suffix ? `discharge-status${suffix}` : 'discharge-status';
            const trendArrowId = suffix ? `trend-arrow${suffix}` : 'trend-arrow';
            const highestInfoId = suffix ? `highest-info${suffix}` : 'highest-info';
            const lowestInfoId = suffix ? `lowest-info${suffix}` : 'lowest-info';

            const dischargeValue = document.getElementById(dischargeValueId);
            const dischargeStatus = document.getElementById(dischargeStatusId);
            const dischargeNumber = Number(data.discharge_m3s);

            if (!Number.isNaN(dischargeNumber)) {
                dischargeValue.textContent = dischargeNumber.toFixed(0);
                const trendText = formatDischargeTrend(data.trend, data.delta_m3s);
                const timeText = data.source_timestamp ? ` | Measurement time: ${data.source_timestamp}` : '';
                dischargeStatus.textContent = trendText + timeText;
                updateTrendArrow(data.trend, trendArrowId);
                
                // Update highest and lowest values
                const highestInfo = document.getElementById(highestInfoId);
                const lowestInfo = document.getElementById(lowestInfoId);
                
                if (highestInfo && data.highest_discharge_m3s) {
                    highestInfo.textContent = `Highest: ${data.highest_discharge_m3s} m³/s (${data.highest_timestamp})`;
                }
                if (lowestInfo && data.lowest_discharge_m3s) {
                    lowestInfo.textContent = `Lowest: ${data.lowest_discharge_m3s} m³/s (${data.lowest_timestamp})`;
                }
            } else {
                dischargeValue.textContent = '--';
                dischargeStatus.innerHTML = `No data parsed <a href="${STATION_PAGE}" target="_blank" rel="noopener">source</a>`;
                updateTrendArrow('unknown', trendArrowId);
            }
        } catch (error) {
            console.error('Error fetching discharge data:', error);
            const dischargeValueId = suffix ? `discharge-value${suffix}` : 'discharge-value';
            const dischargeStatusId = suffix ? `discharge-status${suffix}` : 'discharge-status';
            const trendArrowId = suffix ? `trend-arrow${suffix}` : 'trend-arrow';
            
            document.getElementById(dischargeValueId).textContent = '--';
            document.getElementById(dischargeStatusId).textContent = 'Data unavailable';
            updateTrendArrow('unknown', trendArrowId);
        }
    }
    
    // Convert WMO weather codes to descriptions
    function getWeatherDescription(code) {
        const weatherCodes = {
            0: 'clear sky',
            1: 'mainly clear',
            2: 'partly cloudy',
            3: 'overcast',
            45: 'foggy',
            48: 'depositing rime fog',
            51: 'light drizzle',
            53: 'moderate drizzle',
            55: 'dense drizzle',
            56: 'light freezing drizzle',
            57: 'dense freezing drizzle',
            61: 'slight rain',
            63: 'moderate rain',
            65: 'heavy rain',
            66: 'light freezing rain',
            67: 'heavy freezing rain',
            71: 'slight snow fall',
            73: 'moderate snow fall',
            75: 'heavy snow fall',
            77: 'snow grains',
            80: 'slight rain showers',
            81: 'moderate rain showers',
            82: 'violent rain showers',
            85: 'slight snow showers',
            86: 'heavy snow showers',
            95: 'thunderstorm',
            96: 'thunderstorm with slight hail',
            99: 'thunderstorm with heavy hail'
        };
        
        return weatherCodes[code] || 'unknown';
    }
    
    // Fetch weather data immediately and then every 30 minutes
    getZurichWeather();
    setInterval(getZurichWeather, 30 * 60 * 1000);
    
    // Fetch discharge data immediately and then every 30 minutes
    getDischargeData(DISCHARGE_URLS.limmat, '');
    getDischargeData(DISCHARGE_URLS.rheinfall, '-rheinfall');
    setInterval(() => {
        getDischargeData(DISCHARGE_URLS.limmat, '');
        getDischargeData(DISCHARGE_URLS.rheinfall, '-rheinfall');
    }, DISCHARGE_UPDATE_INTERVAL);
    
    // Load menu
    async function loadMenu() {
        try {
            const menuContainer = document.getElementById('menu-pdf-container');
            if (!menuContainer) return;
            
            menuContainer.innerHTML = '<p class="menu-loading">Loading menu...</p>';
            
            // Load menu JSON
            const response = await fetch('data/menus/menu.json?t=' + Date.now());
            if (!response.ok) {
                throw new Error('Menu JSON not found');
            }
            
            const menuData = await response.json();
            console.log('Menu data loaded:', menuData);
            
            displayMenu(menuContainer, menuData);
        } catch (error) {
            console.error('Error loading menu:', error);
            const menuContainer = document.getElementById('menu-pdf-container');
            if (menuContainer) {
                menuContainer.innerHTML = '<p class="menu-error">Menu could not be loaded</p>';
            }
        }
    }
    
    function displayMenu(container, menuData) {
        const today = new Date();
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);
        
        // Days array
        const days = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag'];
        
        // Get today and tomorrow day names
        let todayIndex = today.getDay() - 1; // 0=Montag
        let tomorrowIndex = tomorrow.getDay() - 1;
        
        // Handle weekends
        if (todayIndex < 0 || todayIndex > 4) todayIndex = 0;
        if (tomorrowIndex < 0 || tomorrowIndex > 4) tomorrowIndex = 0;
        
        const todayName = days[todayIndex];
        const tomorrowName = days[tomorrowIndex];
        
        const todayMenu = menuData.menu[todayName] || [];
        const tomorrowMenu = menuData.menu[tomorrowName] || [];
        
        let html = '<div class="menu-days">';
        
        // Today
        html += `<div class="menu-day">
            <h3>Today (${todayName})</h3>
            <ul class="menu-items">`;
        
        if (todayMenu.length > 0) {
            todayMenu.forEach(item => {
                html += `<li>${item}</li>`;
            });
        } else {
            html += '<li class="no-menu">No menu available</li>';
        }
        
        html += `</ul>
        </div>`;
        
        // Tomorrow
        html += `<div class="menu-day">
            <h3>Tomorrow (${tomorrowName})</h3>
            <ul class="menu-items">`;
        
        if (tomorrowMenu.length > 0) {
            tomorrowMenu.forEach(item => {
                html += `<li>${item}</li>`;
            });
        } else {
            html += '<li class="no-menu">No menu available</li>';
        }
        
        html += `</ul>
        </div>`;
        
        html += '</div>';
        
        container.innerHTML = html;
    }
    
    // Load menu immediately and then every hour
    loadMenu();
    setInterval(loadMenu, 60 * 60 * 1000);
    
    // Add mouse hover effect to URL element
    urlElement.addEventListener('mouseenter', function() {
        this.style.animationPlayState = 'paused';
        this.style.transform = 'scale(1.1)';
        this.style.transition = 'transform 0.3s ease';
    });
    
    urlElement.addEventListener('mouseleave', function() {
        this.style.animationPlayState = 'running';
        this.style.transform = 'scale(1)';
    });
    
    // Add typewriter effect to element
    function typeWriter(element, text, speed = 100) {
        let i = 0;
        element.textContent = '';
        
        function type() {
            if (i < text.length) {
                element.textContent += text.charAt(i);
                i++;
                setTimeout(type, speed);
            }
        }
        type();
    }
    
    // Start typewriter effect after delay
    setTimeout(() => {
        typeWriter(comingSoonElement, 'more to come....', 150);
    }, 1000);
    
    // Add parallax effect on mouse movement
    document.addEventListener('mousemove', function(e) {
        const mouseX = e.clientX / window.innerWidth;
        const mouseY = e.clientY / window.innerHeight;
        
        urlElement.style.transform = `translateY(${-10 + mouseY * 5}px) translateX(${mouseX * 5}px)`;
    });
    
    // Add click effect to URL element
    urlElement.addEventListener('click', function() {
        this.style.transform = 'scale(0.95)';
        setTimeout(() => {
            this.style.transform = 'scale(1)';
        }, 150);
    });
    
    // Smooth color transition animation for background
    let hue = 0;
    setInterval(() => {
        hue = (hue + 0.1) % 360;
        document.body.style.background = `linear-gradient(135deg, hsl(${hue}, 70%, 60%) 0%, hsl(${hue + 60}, 70%, 50%) 100%)`;
    }, 50);
}); 